package ai.eva.android.probe;
import android.app.*;import android.os.*;import android.content.*;import android.widget.*;import org.json.*;

/** Official Codex account flow. Passwords and OAuth tokens never enter Eva's UI bridge. */
public class AccountActivity extends ToolPageActivity {
 KernelHost host;LinearLayout box;TextView status,details,quotaDetails;boolean busy,resumed;Handler timer=new Handler();JSONArray models=new JSONArray();JSONObject account;Button loginButton,reopenButton,cancelButton,backupButton,modelButton,logoutButton,quotaButton;
 final Runnable poll=new Runnable(){public void run(){if(resumed){if(!busy&&host.loginSession!=null)refresh();timer.postDelayed(this,4000);}}};
 public void onCreate(Bundle b){super.onCreate(b);host=KernelHost.get(this);page("OpenAI / ChatGPT 账号","");show();}
 android.content.SharedPreferences prefs(){return getSharedPreferences("eva-account",0);}
 void show(){clear();ScrollView scroll=new ScrollView(this);box=new LinearLayout(this);box.setOrientation(1);scroll.addView(box);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));status=label("正在读取账号状态…",16);box.addView(status);details=label("",13);details.setTextIsSelectable(true);box.addView(details);quotaDetails=label("登录后可查看账号额度",14);quotaDetails.setTextIsSelectable(true);quotaDetails.setVisibility(8);box.addView(quotaDetails);quotaButton=button("查看账号额度",()->startActivity(new Intent(this,ShellActivity.class).putExtra("panel","account")));box.addView(quotaButton);
  loginButton=button("登录 OpenAI / ChatGPT 账号",()->login());box.addView(loginButton);
  box.addView(label("点击登录后打开手机 Chrome，完成官方网页授权即可。无需手动复制验证码。",12));
  reopenButton=button("重新打开登录网页",()->openLogin());box.addView(reopenButton);backupButton=button("其他登录方式",()->new AlertDialog.Builder(this).setTitle("备用登录方式").setItems(new String[]{"使用设备码授权"},(d,n)->deviceLogin()).setNegativeButton("取消",null).show());box.addView(backupButton);cancelButton=button("取消本次登录",()->cancelLogin());box.addView(cancelButton);box.addView(button("刷新账号与额度",()->refresh()));modelButton=button("模型与推理强度",()->chooseModel());box.addView(modelButton);logoutButton=button("退出账号",()->new AlertDialog.Builder(this).setTitle("退出此手机的 OpenAI 账号？").setMessage("清除此内核的登录状态；API 提供商和聊天记录保留。").setPositiveButton("退出",(d,w)->logout()).setNegativeButton("取消",null).show());box.addView(logoutButton);box.addView(label("使用此账号的 Codex 模型与额度；具体可用性以服务端返回为准。账号凭据由手机内的 Codex 内核管理，不复制桌面登录信息。",12));updateButtons();}
 void updateButtons(){boolean signed=account!=null,pending=host.loginSession!=null;loginButton.setVisibility(!signed&&!pending?0:8);backupButton.setVisibility(!signed&&!pending?0:8);reopenButton.setVisibility(!signed&&pending?0:8);cancelButton.setVisibility(!signed&&pending?0:8);modelButton.setVisibility(signed?0:8);quotaButton.setVisibility(signed?0:8);logoutButton.setVisibility(signed?0:8);for(Button b:new Button[]{loginButton,backupButton,reopenButton,cancelButton,modelButton,logoutButton})b.setEnabled(!busy);}
 interface Request {JSONObject run()throws Exception;}
 interface Done {void accept(JSONObject result)throws Exception;}
 void request(String message,Request call,Done done){if(busy)return;busy=true;status.setText(message);updateButtons();host.work.execute(()->{try{JSONObject result=call.run();runOnUiThread(()->{busy=false;if(isFinishing()||isDestroyed())return;try{done.accept(result);}catch(Exception e){status.setText("账号数据暂时无法显示，请刷新");}finally{updateButtons();}});}catch(Exception e){runOnUiThread(()->{busy=false;if(host.loginSession==null)LoginService.end(this);if(!isFinishing()&&!isDestroyed())status.setText("请求失败："+host.redact(e.getMessage()==null?"请检查网络后重试":e.getMessage()));if(!isDestroyed())updateButtons();});}});}
 void login(){if(host.loginSession!=null){displayLogin();openLogin();return;}LoginService.begin(this);request("正在打开官方账号登录…",()->host.nativeRequest("account/login/start",new JSONObject().put("type","chatgpt")),r->{displayLogin();openLogin();});}
 void deviceLogin(){if(host.loginSession!=null){status.setText("请先取消当前登录，再使用备用方式");return;}LoginService.begin(this);request("正在申请备用验证码…",()->host.nativeRequest("account/login/start",new JSONObject().put("type","chatgptDeviceCode")),r->displayLogin());}
 void displayLogin(){JSONObject login=host.loginSession;if(login==null){details.setText("");return;}status.setText("等待你完成账号授权");updateButtons();if("chatgpt".equals(login.optString("type"))){details.setText("请在 Chrome 完成登录和授权，完成后返回 Eva。登录结果会自动更新。");return;}details.setText("一次性验证码："+login.optString("userCode")+"\n授权地址："+login.optString("verificationUrl")+"\n\n备用方式：在 Chrome 登录后填写以上验证码。可长按选择复制。完成后返回此页；验证码失效时，请取消后重新申请。");}
 void openLogin(){JSONObject login=host.loginSession;if(login==null){status.setText("请先点击登录，申请验证码");return;}try{String url=login.getString("chatgpt".equals(login.optString("type"))?"authUrl":"verificationUrl");android.net.Uri uri=android.net.Uri.parse(url);if(!"https".equals(uri.getScheme())||!"auth.openai.com".equals(uri.getHost()))throw new Exception();LoginService.begin(this);Intent browserIntent=new Intent(Intent.ACTION_VIEW,uri);try{startActivity(browserIntent.setPackage("com.android.chrome"));}catch(ActivityNotFoundException missingChrome){startActivity(browserIntent.setPackage(null));}}catch(Exception e){status.setText("授权地址无效，请重新申请登录");}}
 void copyCode(){JSONObject login=host.loginSession;if(login==null){status.setText("尚未申请验证码");return;}((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("OpenAI 一次性验证码",login.optString("userCode")));Toast.makeText(this,"验证码已复制",Toast.LENGTH_SHORT).show();}
 void cancelLogin(){JSONObject login=host.loginSession;if(login==null){status.setText("没有待处理的登录");return;}request("正在取消登录…",()->host.nativeRequest("account/login/cancel",new JSONObject().put("loginId",login.getString("loginId"))),r->{LoginService.end(this);details.setText("");status.setText("已取消登录");});}
 void refresh(){request("正在读取账号…",()->host.nativeRequest("account/read",new JSONObject().put("refreshToken",false)),r->{account=r.optJSONObject("account");if(account==null){quotaDetails.setText("登录后可查看账号额度");if(host.loginSession!=null)displayLogin();else{status.setText(host.loginError.isEmpty()?"尚未登录 OpenAI / ChatGPT 账号":host.loginError);details.setText("");}return;}status.setText("已登录 · "+account.optString("planType",""));details.setText(account.optString("email",""));loadModelsAndQuota();});}
 void loadModelsAndQuota(){request("正在读取模型与额度…",()->{JSONObject result=new JSONObject();try{result.put("models",host.nativeRequest("model/list",new JSONObject().put("limit",100)));}catch(Exception e){result.put("modelsError",true);}try{result.put("quota",host.nativeRequest("account/rateLimits/read",new JSONObject()));}catch(Exception e){result.put("quotaError",true);}return result;},r->{JSONObject catalog=r.optJSONObject("models");models=catalog==null?new JSONArray():catalog.optJSONArray("data");if(models==null)models=new JSONArray();String selected=prefs().getString("model","");boolean found=false;String fallback="";for(int i=0;i<models.length();i++){JSONObject m=models.getJSONObject(i);if(m.optBoolean("hidden"))continue;String id=m.optString("model",m.optString("id"));if(id.equals(selected))found=true;if(fallback.isEmpty()||m.optBoolean("isDefault"))fallback=id;}if(!found&&!fallback.isEmpty())prefs().edit().putString("model",fallback).apply();status.setText("已登录 · "+account.optString("planType",""));JSONObject quota=r.optJSONObject("quota");quotaDetails.setText("OpenAI / Codex 额度\n\n"+AccountQuota.describe(quota));String text=account.optString("email","")+"\n默认模型："+prefs().getString("model","尚未获取")+"\n";if(r.optBoolean("modelsError"))text+="\n模型列表获取失败，请稍后刷新";details.setText(text);});}
 void chooseModel(){startActivity(new Intent(this,ShellActivity.class).putExtra("panel","models"));}
 void logout(){request("正在退出…",()->host.nativeRequest("account/logout",new JSONObject()),r->{LoginService.end(this);account=null;models=new JSONArray();prefs().edit().putBoolean("loggedIn",false).putBoolean("preferred",false).remove("model").commit();status.setText("已退出账号");details.setText("");quotaDetails.setText("登录后可查看账号额度");});}
 protected void onResume(){super.onResume();resumed=true;refresh();timer.postDelayed(poll,4000);}
 protected void onPause(){resumed=false;timer.removeCallbacks(poll);super.onPause();}
}
